#!/usr/bin/env bash
set -e
# QR de conductor + vehiculo y jornada (inicio/fin de turno):
# - Nuevos modelos VehicleQrToken y DriverShift (aditivos, no tocan tablas
#   existentes).
# - Backend: servicio de emision/resolucion de QR, endpoint que la App
#   Conductor YA llamaba desde antes (ScanVehicleQrPage.tsx llevaba tiempo
#   integrado mirando a un endpoint que nunca se habia montado, igual que
#   paso con el GPS), y endpoints de jornada (start/end/current).
# - App Conductor: se enruta la pantalla de escaneo QR (antes inalcanzable)
#   y se anade una barra de jornada en la pantalla de Ruta de hoy.
# - Backoffice: en Flota > Vehiculos, boton para ver/generar el QR de cada
#   vehiculo (con imagen QR vía servicio gratuito sin API key); en Flota >
#   Conductores, columna "Jornada" con quien esta de turno ahora mismo.
# Requiere "npx prisma db push" (cambio de schema). Ejecutar desde la raiz
# del repo.

echo "Escribiendo backend/prisma/schema.prisma..."
mkdir -p "$(dirname backend/prisma/schema.prisma)"
base64 -d > backend/prisma/schema.prisma <<'B64EOF'
